      .fontSize($r("app.float.body_medium"))
      .padding({ left: 10, right: 10 })
      .onClick((): void => this.handleSearch());
  }

  /**
   * 触发搜索
   * @returns {void} 无返回值
   */
  private handleSearch(): void {
    this.onSearch(this.value);
  }
}

