import { NetworkResponse } from "model";
import { ToastUtils } from "util";

/**
 * @file 网络请求结果处理
 * @description 提供网络请求结果处理的助手类，自动处理异常以及简化相关代码。
 * @param T 网络请求返回数据项类型
 * @author Joker.X
 */
export class RequestHelper<T> {
  /**
   * 原始请求 Promise，类型为 NetworkResponse<T>
   */
  private source: Promise<NetworkResponse<T>>;
  /**
   * 是否为本次请求显示 loading，默认 false
   */
  private useLoading: boolean = false;
  /**
   * 是否为本次请求自动 toast 错误，默认 true
   */
  private useToast: boolean = true;
  /**
   * 请求开始前的回调（如埋点、重置状态）
   */
  private beforeStart?: () => void;

  /**
   * 构造函数
   * @param {Promise<NetworkResponse<T>>} promise - 原始请求 Promise
   */
  private constructor(promise: Promise<NetworkResponse<T>>) {
    this.source = promise;
  }

  /**
   * 配置请求源仓库（Repository/API 返回的 Promise）
   * @param {Promise<NetworkResponse<T>>} promise - 原始请求 Promise
   * @returns {RequestHelper<T>} 链式助手实例
   */
  static repository<T>(promise: Promise<NetworkResponse<T>>): RequestHelper<T> {
    return new RequestHelper<T>(promise);
  }

  /**
   * 设置请求开始前执行的回调
   * @param {() => void} handler - 前置回调
   * @returns {RequestHelper<T>} 当前实例
   */
  start(handler: () => void): RequestHelper<T> {
    this.beforeStart = handler;
    return this;
  }

  /**
   * 返回完整响应（code / data / message），需手动调用 then 处理
   * @returns {Promise<NetworkResponse<T>>} 完整响应 Promise
   */
  async response(): Promise<NetworkResponse<T>> {
    return this.runInternal(true);
  }

  /**
   * 配置是否展示 loading
   * @param {boolean} enable - 是否展示
   * @returns {RequestHelper<T>} 当前实例
   */
  loading(enable: boolean = false): RequestHelper<T> {
    this.useLoading = enable;
    return this;
  }

  /**
   * 配置是否自动 toast 错误
   * @param {boolean} enable - 是否展示
   * @returns {RequestHelper<T>} 当前实例
   */
  toast(enable: boolean = true): RequestHelper<T> {
    this.useToast = enable;
    return this;
  }

  /**
   * 执行请求，可 await 或 .then，默认仅返回 data
   * @returns {Promise<T>} data Promise
   */
  async execute(): Promise<T> {
    return this.runInternal(false);
  }

  /**
   * 内部执行重载：true 返回响应，false 返回 data
   */
  private async runInternal(returnFull: true): Promise<NetworkResponse<T>>;

  private async runInternal(returnFull: false): Promise<T>;

  /**
   * 核心执行逻辑
   * @param {boolean} returnFull - 是否返回完整响应
   * @returns {Promise<NetworkResponse<T> | T>} 结果
   */
  private async runInternal(returnFull: boolean): Promise<NetworkResponse<T> | T> {
    if (this.beforeStart) {
      this.beforeStart();
    }
    if (this.useLoading) {
      ToastUtils.showLoading();
    }
    try {
      const rawResp: NetworkResponse<T> = await this.source;
      const resp: NetworkResponse<T> = new NetworkResponse<T>(rawResp);
      if (resp.isSucceeded) {
        if (returnFull) {
          return resp;
        }
        return resp.data as T;
      }
      const bizMsg: string = resp.message ?? "业务失败";
      this.toastIfNeeded(bizMsg);
      throw new Error(bizMsg);
    } catch (e) {
      const err: Error = e instanceof Error ? e : new Error("网络异常");
      this.toastIfNeeded(err.message);
      throw err;
    } finally {
      if (this.useLoading) {
        ToastUtils.hide();
      }
    }
  }

  /**
   * 按需弹出错误提示
   * @param {string} message - 错误信息
   */
  private toastIfNeeded(message: string): void {
    if (this.useToast) {
      ToastUtils.showError(message);
    }
  }
}

import { P100, SpaceVerticalXSmall } from "designsystem";
import { Category } from "model";
import { bp } from "state";
import { Card, NetWorkImage } from "ui";

/**
 * @file 首页分类卡片组件
 * @author Joker.X
 */
@ComponentV2
export struct HomeCategorySection {
  /**
   * 分类列表
   */
  @Param
  categories: Category[] = [];
  /**
   * 分类点击回调
   */
  @Param
  onCategoryClick: (id: number) => void = () => {
  };

  /**
   * 构建分类卡片
   * @returns {void} 无返回值
   */
  build(): void {
    if (this.categories && this.categories.length > 0) {
      Card({ paddingValue: $r("app.float.space_padding_small") }) {
        Grid() {
          ForEach(this.categories, (category: Category): void => {
            GridItem() {
              this.categoryItem(category);
            }
          }, (category: Category): string => `${category.id}-${category.name}`);
        }
        .columnsTemplate(this.buildColumnsTemplate())
        .columnsGap($r("app.float.space_horizontal_small_x"))
        .rowsGap($r("app.float.space_vertical_small_x"))
        .width(P100);
      }
    }
  }

  /**
   * 分类项视图
   * @param {Category} category - 分类数据
   * @returns {void} 无返回值
   */
  @Builder
  private categoryItem(category: Category): void {
    Column() {
      NetWorkImage({
        model: category.pic ?? null,
        sizeValue: this.getImageSize(),
        cornerRadius: this.getImageRadius(),
        showBackground: true,
        backgroundColorValue: $r("app.color.bg_grey")
      });

      SpaceVerticalXSmall();

      Text(category.name)
        .fontSize($r("app.float.headline_medium"))
        .fontColor($r("app.color.text_primary"))
        .maxLines(1)
        .textOverflow({ overflow: TextOverflow.Ellipsis });
    }
    .width(P100)
    .padding({
      top: $r("app.float.space_vertical_small_x"),
      bottom: $r("app.float.space_vertical_small_x")
    })
    .alignItems(HorizontalAlign.Center)
    .onClick((): void => this.onCategoryClick(category.id));
  }

  /**
   * 获取列数模板
   * @returns {string} Grid 列模板
   */
  private buildColumnsTemplate(): string {
    const columns: number = this.getColumnsCount();
    let template: string = "";
    for (let index: number = 0; index < columns; index++) {
      template = `${template}1fr${index === columns - 1 ? "" : " "}`;
    }
    return template;
  }

  /**
   * 获取当前断点对应的列数
   * @returns {number} 列数
   */
  private getColumnsCount(): number {
    return bp({ sm: 5, md: 10, lg: 10 });
  }

  /**
   * 获取分类图标尺寸
   * @returns {number} 图标尺寸
   */
  private getImageSize(): number {
    return bp({ sm: 48, md: 56, lg: 60 });
  }

  /**
   * 获取分类图标圆角
   * @returns {number} 图标圆角
   */
  private getImageRadius(): number {
    const size: number = this.getImageSize();
    return size / 2;
  }
}

import { BaseNetWorkViewModel } from "base";
import { GoodsRepository } from "data";
import { Category, CategoryTree, NetworkResponse } from "model";

/**
 * @file 分类页面 ViewModel
 * @author Joker.X
 */
@ObservedV2
export default class CategoryViewModel extends BaseNetWorkViewModel<Category[]> {
  /**
   * 商品仓库
   */
  private goodsRepository: GoodsRepository = new GoodsRepository();
  /**
   * 分类树数据
   */
  @Trace
  categoryTrees: CategoryTree[] = [];
  /**
   * 左侧分类标题列表
   */
  @Trace
  categoryTitles: string[] = [];
  /**
   * 当前选中的分类索引
   */
  @Trace
  selectedCategoryIndex: number = -1;
  /**
   * 是否正在执行侧边栏联动滚动
   */
  @Trace
  isSideBarScrolling: boolean = false;
  /**
   * 侧边栏上一次选中索引
   */
  @Trace
  lastSideBarIndex: number = 0;
  /**
   * 侧边栏联动滚动解锁计时器
   */
  private sideBarUnlockTimer: number = -1;

  /**
   * 重写请求方法来实现网络请求
   *
   * @return 商品分类
   */
  protected requestRepository(): Promise<NetworkResponse<Category[]>> {
    return this.goodsRepository.getGoodsTypeList();
  }

  /**
   * 请求成功后处理分类树数据
   * @param {Category[]} data - 分类列表
   * @returns {void} 无返回值
   */
  protected onRequestSuccess(data: Category[]): void {
    this.categoryTrees = this.convertToTree(data);
    this.categoryTitles = this.categoryTrees.map((item: CategoryTree): string => item.name);
    this.isSideBarScrolling = false;
    this.lastSideBarIndex = 0;
    this.clearSideBarUnlockTimer();
    if (this.categoryTrees.length > 0) {
      if (this.selectedCategoryIndex < 0 || this.selectedCategoryIndex >= this.categoryTrees.length) {
        this.selectedCategoryIndex = 0;
      }
    } else {
      this.selectedCategoryIndex = -1;
    }
    super.onRequestSuccess(data);
  }

  /**
   * 处理侧边栏选中事件
   * @param {number} index - 目标索引
   * @returns {number} 实际滚动目标索引
   */
  onSideBarSelected(index: number): number {
    const targetIndex: number = this.clampIndex(index);
    this.isSideBarScrolling = true;
    this.selectedCategoryIndex = targetIndex;
    this.startSideBarUnlockTimer(targetIndex);
    return targetIndex;
  }

  /**
   * 结束侧边栏联动滚动
   * @returns {void} 无返回值
   */
  finishSideBarScroll(): void {
    this.isSideBarScrolling = false;
  }

  /**
   * 处理右侧列表滚动事件
   * @param {number} startIndex - 当前可见起始索引
   * @returns {void} 无返回值
   */
  onRightListScroll(startIndex: number): void {
    if (startIndex < 0) {
      return;
    }
    if (this.isSideBarScrolling) {
      return;
    }
    if (startIndex !== this.selectedCategoryIndex) {
      this.selectedCategoryIndex = startIndex;
    }
  }

  /**
   * 获取侧边栏当前激活索引
   * @returns {number} 当前激活索引
   */
  getActiveIndex(): number {
    return this.selectedCategoryIndex < 0 ? 0 : this.selectedCategoryIndex;
  }

  /**
   * 校验侧边栏索引合法性
   * @param {number} index - 原始索引
   * @returns {number} 合法索引，不合法返回 -1
   */
  private clampIndex(index: number): number {
    const total: number = this.categoryTrees.length;
    if (total <= 0) {
      return 0;
    }
    if (index < 0) {
      return 0;
    }
    if (index >= total) {
      return total - 1;
    }
    return index;
  }

  /**
   * 计算联动解锁时长
   * @param {number} targetIndex - 目标索引
   * @returns {number} 解锁时长（毫秒）
   */
  private calculateUnlockDuration(targetIndex: number): number {
    const distance: number = Math.abs(targetIndex - this.lastSideBarIndex);
    this.lastSideBarIndex = targetIndex;
    return Math.min(1200, Math.max(240, distance * 120));
  }

  /**
   * 启动侧边栏联动解锁计时器
   * @param {number} targetIndex - 目标索引
   * @returns {void} 无返回值
   */
  private startSideBarUnlockTimer(targetIndex: number): void {
    this.clearSideBarUnlockTimer();
    const duration: number = this.calculateUnlockDuration(targetIndex);
    this.sideBarUnlockTimer = setTimeout((): void => {
      this.finishSideBarScroll();
      this.sideBarUnlockTimer = -1;
    }, duration);
  }

  /**
   * 清理侧边栏联动解锁计时器
   * @returns {void} 无返回值
   */
  private clearSideBarUnlockTimer(): void {
    if (this.sideBarUnlockTimer >= 0) {
      clearTimeout(this.sideBarUnlockTimer);
      this.sideBarUnlockTimer = -1;
    }
  }

  /**
   * 页面隐藏时清理计时器
   * @returns {void} 无返回值
   */
  aboutToDisappear(): void {
    this.clearSideBarUnlockTimer();
  }

  /**
   * 页面销毁时清理计时器
   * @returns {void} 无返回值
   */
  aboutToBeDeleted(): void {
    this.clearSideBarUnlockTimer();
  }

  /**
   * 将分类列表转换为树形结构
   * @param {Category[]} categories - 原始分类列表
   * @returns {CategoryTree[]} 树形结构的分类列表
   * @example
  * const tree = this.convertToTree(list);
   */
  private convertToTree(categories: Category[]): CategoryTree[] {
    if (!categories || categories.length === 0) {
      return [];
    }

    const nestedTrees: CategoryTree[] = this.tryBuildTreeFromNested(categories);
    if (nestedTrees.length > 0) {
      return nestedTrees;
    }

    const sortedList: Category[] = [...categories].sort((a: Category, b: Category): number => a.sortNum - b.sortNum);
    const categoryTrees: CategoryTree[] =
      sortedList.map((item: Category): CategoryTree => CategoryTree.fromCategory(item));
    const rootCategories: CategoryTree[] = [];
    const childrenMap: Map<number, CategoryTree[]> = new Map<number, CategoryTree[]>();

    categoryTrees.forEach((categoryTree: CategoryTree): void => {
      const parentId: number | null | undefined = categoryTree.parentId;
      if (parentId === null || parentId === undefined || parentId === 0) {
        rootCategories.push(categoryTree);
        return;
      }
      const children: CategoryTree[] = childrenMap.get(parentId) ?? [];
      children.push(categoryTree);
      childrenMap.set(parentId, children);
    });

    return rootCategories.map((rootCategory: CategoryTree): CategoryTree => this.buildCategoryTree(rootCategory,
      childrenMap));
  }

  /**
   * 递归构建分类树
   * @param {CategoryTree} categoryTree - 当前分类节点
   * @param {Map<number, CategoryTree[]>} childrenMap - 子分类映射
   * @returns {CategoryTree} 构建完成的分类节点
   */
  private buildCategoryTree(categoryTree: CategoryTree, childrenMap: Map<number, CategoryTree[]>): CategoryTree {
    const children: CategoryTree[] = childrenMap.get(categoryTree.id) ?? [];
    if (children.length === 0) {
      return categoryTree;
    }
    categoryTree.children =
      children.map((child: CategoryTree): CategoryTree => this.buildCategoryTree(child, childrenMap));
    return categoryTree;
  }

  /**
   * 尝试从已包含 children 的数据中构建树
   * @param {Category[]} categories - 原始分类列表
   * @returns {CategoryTree[]} 构建后的树结构
   */
  private tryBuildTreeFromNested(categories: Category[]): CategoryTree[] {
    const hasChildren: boolean = categories.some((item: Category): boolean => {
      return (item.children ?? []).length > 0;
    });
    if (!hasChildren) {
      return [];
    }
    return categories.map((item: Category): CategoryTree => this.convertNestedNode(item));
  }

  /**
   * 递归转换带 children 的节点
   * @param {Category} category - 原始分类节点
   * @returns {CategoryTree} 转换后的分类树节点
   */
  private convertNestedNode(category: Category): CategoryTree {
    const node: CategoryTree = CategoryTree.fromCategory(category);
    const children: Category[] = category.children ?? [];
    if (children.length > 0) {
      node.children = children.map((child: Category): CategoryTree => this.convertNestedNode(child));
    }
    return node;
  }
}

import { ColumnStart, P100, RowStartTop, SpaceVerticalSmall, SpaceVerticalXSmall } from "designsystem";
import { CategoryTree } from "model";
import { bp, getWindowSafeAreaState, WindowSafeAreaState } from "state";
import { IBestSideBar, IBestSideBarItem } from "ibestui";
import { AppNavDestination, BaseNetWorkView, NetWorkImage, TitleWithLine } from "ui";
import CategoryViewModel from "../viewmodel/CategoryViewModel";

/**
 * @file 分类页面视图
 * @author Joker.X
 */
@ComponentV2
export struct CategoryPage {
  /**
   * 分类页面 ViewModel
   */
  @Local
  private vm: CategoryViewModel = new CategoryViewModel();
  /**
   * 当前窗口安全区状态
   */
  @Local
  private windowSafeAreaState: WindowSafeAreaState = getWindowSafeAreaState();
  /**
   * 右侧列表滚动控制器
   */
  private rightListScroller: Scroller = new Scroller();
  /**
   * 侧边栏分组 ID
   */
  private sideBarGroupId: string = "category-side-bar";

  /**
   * 构建分类页面
   * @returns {void} 无返回值
   */
  build() {
    AppNavDestination({
      title: $r("app.string.category"),
      viewModel: this.vm,
      pageBackgroundColor: $r("app.color.bg_white"),
      paddingValue: {
        top: this.windowSafeAreaState.topInset,
        left: this.windowSafeAreaState.leftInset,
        right: this.windowSafeAreaState.rightInset
      },
      titleOptions: {
        backgroundColor: $r("app.color.bg_white")
      }
    }) {
      BaseNetWorkView({
        uiState: this.vm.uiState,
        onRetry: (): void => this.vm.retryRequest(),
        content: (): void => this.CategoryContent()
      })
    }
  }

  /**
   * 分类页面内容视图
   * @returns {void} 无返回值
   */
  @Builder
  private CategoryContent(): void {
    RowStartTop({ fillMaxSize: true }) {
      if (this.vm.categoryTitles.length > 0) {
        Column() {
          IBestSideBar({
            groupId: this.sideBarGroupId,
            active: this.vm.getActiveIndex(),
            activeFontColor: $r("app.color.primary"),
            bgColor: $r("app.color.bg_grey"),
            activeBgColor: $r("app.color.bg_white"),
            sideWidth: bp({ sm: 80, md: 100, lg: 120 }),
            onChange: (index: number): void => this.onSideBarChange(index)
          }) {
            ForEach(this.vm.categoryTitles, (item: string, index: number): void => {
              IBestSideBarItem({
                groupId: this.sideBarGroupId,
                index: index,
                title: item,
                contentPadding: {
                  top: $r("app.float.space_vertical_large"),
                  bottom: $r("app.float.space_vertical_large")
                }
              });
              SpaceVerticalSmall()
            }, (item: string, index: number): string => `${index}-${item}`);
          }
        }
        .height(P100)
        .backgroundColor($r("app.color.bg_grey"))
      }

      Column() {
        List({
          space: 12,
          scroller: this.rightListScroller
        }) {
          ForEach(this.vm.categoryTrees, (item: CategoryTree, index: number): void => {
            ListItem() {
              this.buildCategorySection(item);
            };
          }, (item: CategoryTree): string => `${item.id}`);
        }
        .padding({
          left: $r("app.float.space_padding_small"),
          right: $r("app.float.space_padding_small"),
          top: $r("app.float.space_padding_small")
        })
        .onScrollIndex((startIndex: number): void => {
          this.onRightListScroll(startIndex);
        })
        .width(P100);
      }
      .alignItems(HorizontalAlign.Start)
      .layoutWeight(1)
      .height(P100)
      .backgroundColor($r("app.color.bg_white"));
    }
  }

  /**
   * 构建右侧分类分区
   * @param {CategoryTree} categoryTree - 分类树节点
   * @returns {void} 无返回值
   */
  @Builder
  private buildCategorySection(categoryTree: CategoryTree): void {
    ColumnStart({
      widthValue: P100,
      paddingValue: {
        bottom: $r("app.float.space_padding_large")
