import {
  ColumnStart,
  P100,
  P65,
  RowSpaceBetweenCenter,
  RowStartCenter,
  SpaceHorizontalSmall,
  SpaceVerticalMedium,
  SpaceVerticalSmall,
  SpaceVerticalXSmall
} from "designsystem";
import { Goods, GoodsSpec, SelectedGoods } from "model";
import { BaseNetWorkUiState } from "base";
import { BottomModal } from "./BottomModal";
import { NetWorkImage } from "../image/NetWorkImage";
import { IBestButton, IBestPrice, IBestStepper } from "ibestui";
import { TitleWithLine } from "../title/TitleWithLine";
import { CommonIcon } from "../icon/CommonIcon";
import { BaseNetWorkView } from "../network/BaseNetWorkView";
import { PageLoading } from "../loading/PageLoading";
import { EmptyNetwork } from "../empty/EmptyNetwork";

/**
 * @file 规格选择弹窗组件
 * @author Joker.X
 */
@ComponentV2
export struct SpecSelectModal {
  /**
   * 是否显示弹窗
   */
  @Param
  @Require
  visible: boolean = false;
  /**
   * 关闭回调
   */
  @Param
  onDismiss: () => void = () => {
  };
  /**
   * 商品信息
   */
  @Param
  goods: Goods | null = null;
  /**
   * 网络请求状态
   */
  @Param
  uiState: BaseNetWorkUiState = BaseNetWorkUiState.LOADING;
  /**
   * 规格列表数据
   */
  @Param
  specList: GoodsSpec[] = [];
  /**
   * 规格选择回调
   * @param {GoodsSpec} spec - 选中的规格
   */
  @Param
  onSpecSelected: (spec: GoodsSpec) => void = () => {
  };
  /**
   * 加入购物车回调
   * @param {SelectedGoods} selectedGoods - 已选商品信息
   */
  @Param
  onAddToCart: (selectedGoods: SelectedGoods) => Promise<void> = async () => {
  };
  /**
   * 立即购买回调
   * @param {SelectedGoods} selectedGoods - 已选商品信息
   */
  @Param
  onBuyNow: (selectedGoods: SelectedGoods) => void = () => {
  };
  /**
   * 重试回调（当网络请求失败时使用）
   */
  @Param
  onRetry: () => void = () => {
  };
  /**
   * 当前已选择的规格
   */
  @Param
  selectedSpec: GoodsSpec | null = null;
  /**
   * 是否为网格模式（true: 网格模式, false: 列表模式）
   */
  @Local
  isGridMode: boolean = true;
  /**
   * 选择的商品数量
   */
  @Local
  quantity: number = 1;

  /**
   * 构建规格选择弹窗
   * @returns {void} 无返回值
   */
  build() {
    BottomModal({
      visible: this.visible,
      title: $r("app.string.modal_select_spec"),
      onDismiss: this.onDismiss,
      content: (): void => this.ModalContentNetWorkLayout()
    });
  }

  /**
   * 弹窗内容包装器（包含网络状态处理）
   * @returns {void} 无返回值
   */
  @Builder
  private ModalContentNetWorkLayout(): void {
    BaseNetWorkView({
      uiState: this.uiState,
      onRetry: this.onRetry,
      loadingBuilder: (): void => this.CustomLoading(),
      errorBuilder: (): void => this.CustomError(),
      content: (): void => this.ModalContent()
    });
  }

  /**
   * 弹窗内容
   * @returns {void} 无返回值
   */
  @Builder
  private ModalContent(): void {
    ColumnStart({ widthValue: P100 }) {
      // 顶部商品信息
      if (this.goods) {
        this.SpecHeaderInfo();
      }

      SpaceVerticalMedium();

      // 规格分类标题和切换按钮
      RowSpaceBetweenCenter({ widthValue: P100 }) {
        TitleWithLine({ text: $r("app.string.spec_category") });

        CommonIcon({
          icon: this.isGridMode ? $r("app.media.ic_menu_list") : $r("app.media.ic_menu"),
          iconSize: 24,
          tintColor: $r("app.color.text_secondary"),
          onTap: () => {
            this.isGridMode = !this.isGridMode;
          }
        });
      }

      SpaceVerticalMedium();

      Scroll() {
        if (this.isGridMode) {
          this.GridSpecSelectionContent();
        } else {
          this.ListSpecSelectionContent();
        }
      }
      .width(P100)
      .constraintSize({ maxHeight: P65 })
      .scrollBar(BarState.Off);

      SpaceVerticalMedium();

      // 数量选择器
      if (this.selectedSpec) {
        this.QuantitySelector();
        SpaceVerticalMedium();
      }

      // 底部操作按钮
      this.SpecBottomButtons();
    }
  }

  /**
   * 顶部商品信息
   * @returns {void} 无返回值
   */
  @Builder
  private SpecHeaderInfo(): void {
    RowStartCenter({ widthValue: P100 }) {
      // 商品图片
      NetWorkImage({
        model: this.selectedSpec?.images?.[0] ?? this.goods?.mainPic ?? "",
        widthValue: 100,
        heightValue: 100,
        cornerRadius: $r("app.float.radius_small")
      });
      SpaceHorizontalSmall();
      // 商品信息
      ColumnStart() {
        // 价格
        IBestPrice({
          value: this.selectedSpec?.price ?? this.goods?.price ?? 0,
          symbolFontSize: 16,
          integerFontSize: 24,
          decimalFontSize: 16,
        });

        SpaceVerticalSmall();

        // 已选规格
        if (this.selectedSpec) {
          Text() {
            Span($r("app.string.spec_selected"))
              .fontSize($r("app.float.body_large"))
              .fontColor($r("app.color.text_secondary"));
            Span(`：${this.selectedSpec.name}`)
              .fontSize($r("app.float.body_large"))
              .fontColor($r("app.color.text_secondary"));
          }
        } else {
          Text($r("app.string.spec_not_selected"))
            .fontSize($r("app.float.body_large"))
            .fontColor($r("app.color.text_secondary"));
        }

        SpaceVerticalXSmall();

        // 库存
        Text() {
          Span($r("app.string.spec_stock"))
            .fontSize($r("app.float.body_large"))
            .fontColor($r("app.color.text_tertiary"));
          Span(`：${this.selectedSpec?.stock ?? 0}`)
            .fontSize($r("app.float.body_large"))
            .fontColor($r("app.color.text_tertiary"));
        }
      }
    }
  }

  /**
   * 底部操作按钮
   * @returns {void} 无返回值
   */
  @Builder
  private SpecBottomButtons(): void {
    Row({ space: 12 }) {
      // 加入购物车按钮
      IBestButton({
        text: $r("app.string.modal_add_to_cart"),
        type: "primary",
        plain: true,
        round: true,
        btnHeight: 38,
        disabled: this.selectedSpec === null || (this.selectedSpec?.stock ?? 0) <= 0,
        btnWidth: P100,
        onBtnClick: () => {
          this.handleAddToCart();
        }
      }).layoutWeight(1);

      // 立即购买按钮
      IBestButton({
        text: $r("app.string.modal_buy_now"),
        type: "primary",
        round: true,
        btnHeight: 38,
        disabled: this.selectedSpec === null || (this.selectedSpec?.stock ?? 0) <= 0,
        btnWidth: P100,
        onBtnClick: () => {
          this.handleBuyNow();
        }
      }).layoutWeight(1);
    }
    .width(P100);
  }

  /**
   * 数量选择器
   * @returns {void} 无返回值
   */
  @Builder
  private QuantitySelector(): void {
    RowSpaceBetweenCenter({ widthValue: P100 }) {
      Text($r("app.string.quantity"))
        .fontSize($r("app.float.body_large"))
        .fontColor($r("app.color.text_primary"));

      IBestStepper({
        value: this.quantity,
        min: 1,
        max: this.selectedSpec?.stock ?? 99,
        buttonRadius: 999,
        minusBtnBgColor: "#fff",
        minusBtnIconColor: $r("app.color.primary"),
        minusBtnBorderColor: $r("app.color.primary"),
        plusBtnBgColor: $r("app.color.primary"),
        plusBtnIconColor: "#fff",
        inputBgColor: "transparent"
      });
    }
  }

  /**
   * 网格模式的规格选择内容
   * @returns {void} 无返回值
   */
  @Builder
  private GridSpecSelectionContent(): void {
    Flex({ wrap: FlexWrap.Wrap, justifyContent: FlexAlign.SpaceBetween }) {
      ForEach(this.specList, (spec: GoodsSpec, index: number) => {
        Column() {
          // 规格图片
          NetWorkImage({
            model: spec.images?.[0] ?? this.goods?.mainPic ?? "",
            widthValue: P100,
            heightValue: 100,
            cornerRadius: $r("app.float.radius_small")
          });

          // 规格名称
          Text(spec.name)
            .fontSize($r("app.float.body_large"))
            .fontColor(this.selectedSpec?.id === spec.id ? $r("app.color.primary") : $r("app.color.text_primary"))
            .textAlign(TextAlign.Center)
            .maxLines(2)
            .textOverflow({ overflow: TextOverflow.Ellipsis })
            .width(P100)
            .height(46)
            .padding({ left: $r("app.float.space_horizontal_small"), right: $r("app.float.space_horizontal_small") });
        }
        .width('31%')
        .constraintSize({ minHeight: 130 })
        .borderRadius($r("app.float.radius_small"))
        .border({
          width: 1,
          color: this.selectedSpec?.id === spec.id ? $r("app.color.primary") : $r("app.color.border")
        })
        .backgroundColor(this.selectedSpec?.id === spec.id ? '#0D465CFF' : Color.Transparent)
        .margin({ bottom: $r("app.float.space_vertical_small") })
        .onClick(() => {
          this.onSpecSelected(spec);
        });
      });
    }
    .width(P100);
  }

  /**
   * 列表模式的规格选择内容
   * @returns {void} 无返回值
   */
  @Builder
  private ListSpecSelectionContent(): void {
    Column({ space: 12 }) {
      ForEach(this.specList, (spec: GoodsSpec, index: number) => {
        Row() {
          // 规格图片
          NetWorkImage({
            model: spec.images?.[0] ?? this.goods?.mainPic ?? "",
            widthValue: 50,
            heightValue: 50,
            cornerRadius: $r("app.float.radius_small")
          });

          // 规格信息
          Column({ space: 4 }) {
            // 规格名称
            Text(spec.name)
              .fontSize($r("app.float.body_large"))
              .fontColor(this.selectedSpec?.id === spec.id ? $r("app.color.primary") : $r("app.color.text_primary"));

            IBestPrice({
              value: spec.price
            });
          }
          .alignItems(HorizontalAlign.Start)
          .margin({ left: $r("app.float.space_horizontal_small") });
        }
        .width(P100)
        .padding($r("app.float.space_padding_small"))
        .borderRadius($r("app.float.radius_small"))
        .border({
          width: 1,
          color: this.selectedSpec?.id === spec.id ? $r("app.color.primary") : $r("app.color.border")
        })
        .backgroundColor(this.selectedSpec?.id === spec.id ? '#0D465CFF' : Color.Transparent)
        .onClick(() => {
          this.onSpecSelected(spec);
        });
      });
    }
    .width(P100);
  }

  /**
   * 自定义加载视图
   * @returns {void} 无返回值
   */
  @Builder
  private CustomLoading(): void {
    Column() {
      PageLoading();
    }
    .width(P100)
    .height(300);
  }

  /**
   * 自定义错误视图
   * @returns {void} 无返回值
   */
  @Builder
  private CustomError(): void {
    Column() {
      EmptyNetwork({
        onAction: this.onRetry
      });
    }
    .width(P100)
    .height(300);
  }

  /**
   * 处理加入购物车
   * @returns {Promise<void>} 无返回值
   */
  private async handleAddToCart(): Promise<void> {
    if (!this.selectedSpec || !this.goods) {
      return;
    }

    const selectedGoods = new SelectedGoods();
    selectedGoods.goodsId = this.goods.id;
    selectedGoods.goodsInfo = this.goods;
    selectedGoods.spec = this.selectedSpec;
    selectedGoods.count = this.quantity;

    await this.onAddToCart(selectedGoods);
    this.onDismiss();
  }

  /**
   * 处理立即购买
   * @returns {void} 无返回值
   */
  private handleBuyNow(): void {
    if (!this.selectedSpec || !this.goods) {
      return;
    }

    const selectedGoods = new SelectedGoods();
    selectedGoods.goodsId = this.goods.id;
    selectedGoods.goodsInfo = this.goods;
    selectedGoods.spec = this.selectedSpec;
    selectedGoods.count = this.quantity;

    this.onBuyNow(selectedGoods);
    this.onDismiss();
  }
}

补充组合边界：两种布局都执行下拉刷新和触底（Q01“商品列表”并未限某种布局）；加载到后续页后再筛选/重置/排序/搜索；末页后换条件；筛选无结果后重置；排序成功后筛选再翻页；筛选/排序请求未结束时换词；分类元数据失败但商品查询成功。这些组合只用于验证上表已有原子项，不新造持久化或复杂手势要求。

## 5. 网络动作、状态机和请求结束约束

### 5.1 状态定义与证据等级

- Q：已提交的完整查询快照，含关键词、有效分类集合、有效价格、排序及本次入口范围。D：筛选面板草稿。V：当前生命周期/查询版本。P：最后成功提交页码。L：已经成功提交的有序商品列表。H：当前查询是否还有下一页（可为未知）。
- Q 与 D 分开源于 Q07 明文“先…调整…再统一确认应用”；分页首屏替换、提交成功页码、版本隔离、失败恢复与loading绑定是 A53–A64 的合理推导。
- 示意图用“请求”表示实际服务查询，不能只改UI。箭头中的“明文”仅修饰动作/结果语义；page=1、loading视图、版本号、错误视图等细节仍按派生级处理。
- 本图描述一种可测的一致性模型，不指定必须使用类名、布尔变量名、取消令牌或具体状态管理库。工程已有 E08–E11 可复用，但未证明目标页已接入。

```mermaid
stateDiagram-v2
    [*] --> Entering
    Entering --> LoadingFirst: 进入分类页 / 请求本次入口首屏（派生）
    Idle --> LoadingFirst: 有效再次搜索 / 请求新Q（明文）
    Idle --> LoadingFirst: 筛选确认或重置后确认 / 请求新Q（明文）
    Idle --> LoadingFirst: 选择不同排序 / 立即请求新Q（明文）
    Empty --> LoadingFirst: 再搜索或确认或改排序 / 请求新Q
    Idle --> LoadingRefresh: 下拉刷新触发 / 请求当前Q首屏（明文）
    Empty --> LoadingRefresh: 可用刷新动作 / 请求当前Q首屏（派生）
    Idle --> LoadingMore: 触底且H允许且无同页在途 / 请求P+1（明文+派生门禁）
    LoadingFirst --> Idle: 当前版本成功且非空 / 替换L,P=1,重算H,结束loading
    LoadingFirst --> Empty: 当前版本成功且空 / L空,P=1,结束loading
    LoadingFirst --> Error: 当前版本失败 / 不提交失败数据,结束loading
    LoadingRefresh --> Idle: 当前版本成功非空 / 替换L,P=1,重算H,结束loading
    LoadingRefresh --> Empty: 当前版本成功空 / 清L,结束loading
    LoadingRefresh --> Error: 当前版本失败 / 不伪装新成功,结束loading
    LoadingMore --> Idle: 当前版本成功 / 尾部追加,P提交为本次页,重算H,结束loading
    LoadingMore --> Idle: 失败 / L和P保留,结束loading,可重取同页
    Error --> LoadingFirst: 再次既定查询动作或已有重试 / 请求首屏（派生）
    LoadingFirst --> LoadingFirst: 新查询意图 / 新V请求或串行保留最新意图（方案策略）
    LoadingRefresh --> LoadingFirst: 刷新在途时搜索或确认或改排序 / 新Q使旧刷新失效（派生）
    LoadingMore --> LoadingFirst: 确认新Q或刷新 / 旧追加失效,从首屏重查（派生）
    Idle --> Idle: 切换布局 / 只换展示,不商品重载（派生）
    Idle --> Idle: 编辑筛选D / 不应用到Q（明文）
    Idle --> Idle: 已知末页触底 / 无下一页请求（派生）
