import zipfile

ROOT = pathlib.Path(__file__).resolve().parents[2]
OUT = ROOT / "workflow/implementation"
AUDIT = OUT / "audit-v3"
AUDIT.mkdir(exist_ok=True)


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write(name, value):
    (OUT / name).write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


prior = json.loads((OUT / "development-source-fingerprint-v2.json").read_text(encoding="utf-8"))
main_files = set(prior["files_sha256"])
main_files.update(["entry/oh-package.json5", "entry/oh-package-lock.json5"])
main_hashes = {name: sha(ROOT / name) for name in sorted(main_files)}
test_hashes = {path.relative_to(ROOT).as_posix(): sha(path) for path in sorted((ROOT / "entry/src/ohosTest").rglob("*")) if path.is_file()}
source = dict(head=prior["head"], main_files_sha256=main_hashes, test_files_sha256=test_hashes,
              main_source_set_sha256=hashlib.sha256(json.dumps(main_hashes, sort_keys=True).encode()).hexdigest(),
              all_source_set_sha256=hashlib.sha256(json.dumps(dict(**main_hashes, **test_hashes), sort_keys=True).encode()).hexdigest(),
              differences_from_v2=[name for name, value in prior["files_sha256"].items() if main_hashes[name] != value])
write("development-source-fingerprint-v3.json", source)

baseline = list(csv.DictReader((ROOT / "logs/analysis-baseline/warning-inventory.csv").open(encoding="utf-8-sig")))
baseline_keys = {(row["file"], int(row["source_line"]), int(row["column"]), row["message"].strip())
                 for row in baseline if row["file"]}
warnings_report = {}
for target in ["default", "emulator", "ohosTest"]:
    attempts = sorted((ROOT / "logs/development").glob(f"implementation-v3-build-{target}-*.command.json"))
    successful = [json.loads(path.read_text(encoding="utf-8-sig")) for path in attempts
                  if json.loads(path.read_text(encoding="utf-8-sig"))["exit_code"] == 0]
    command = successful[-1]
    log = command["log"]
    lines = (ROOT / log).read_text(encoding="utf-8-sig").splitlines()
    warnings = []
    for index, line in enumerate(lines):
        match = re.search(r"WARN File: (.+):(\d+):(\d+)\s*$", line)
        if match:
            message = next((item.strip() for item in lines[index + 1:] if item.strip()), "")
            warnings.append(dict(file=match[1], source_line=int(match[2]), column=int(match[3]), message=message))
    keys = {(item["file"], item["source_line"], item["column"], item["message"]) for item in warnings}
    warnings_report[target] = dict(command=command, warning_occurrences=len(warnings),
                                    new_unique_diagnostics=sorted(keys - baseline_keys), warnings=warnings)
write("development-warning-comparison-v3.json", warnings_report)

tokens = ["FixtureAbility", "ControlledGoodsDataSource", "FixtureController", "FixtureRequestQueue",
          "GoodsCategoryFixturePage", "gcf.control.", "CML24Fixture", "fixture_pages", "gcf_start"]
artifacts = []
for target in ["default", "emulator", "ohosTest"]:
    paths = sorted((ROOT / f"entry/build/default/outputs/{target}").glob("*.hap"))
    for path in paths:
        with zipfile.ZipFile(path) as archive:
            entries = archive.namelist()
            token_hits = []
            modules = {}
            profiles = {}
            abc_files = []
            for entry in entries:
                data = archive.read(entry)
                for token in tokens:
                    encodings = [encoding for encoding in ["utf-8", "utf-16-le"] if token.encode(encoding) in data]
                    if encodings: token_hits.append(dict(entry=entry, token=token, encodings=encodings))
                if entry.endswith("module.json") or entry.endswith("app.json"):
                    try: modules[entry] = json.loads(data.decode("utf-8"))
                    except (UnicodeError, ValueError): modules[entry] = "not_utf8_json"
                if "/profile/" in entry and entry.endswith(".json"):
                    try: profiles[entry] = json.loads(data.decode("utf-8"))
                    except (UnicodeError, ValueError): profiles[entry] = "not_utf8_json"
                if entry.endswith(".abc"):
                    strings = re.findall(rb"[\x20-\x7e]{4,}", data)
                    listing = AUDIT / f"{target}-{entry.replace('/', '_')}-strings.txt"
                    listing.write_bytes(b"\n".join(strings) + b"\n")
                    abc_files.append(dict(entry=entry, sha256=hashlib.sha256(data).hexdigest(),
                                          strings_file=listing.relative_to(ROOT).as_posix(), strings_sha256=sha(listing)))
        present = sorted({hit["token"] for hit in token_hits})
        artifacts.append(dict(target=target, path=path.relative_to(ROOT).as_posix(), bytes=path.stat().st_size,
                              sha256=sha(path), native_libraries=[entry for entry in entries if entry.endswith(".so")],
