                      haps=[{key: artifact[key] for key in ["target", "path", "bytes", "sha256", "native_libraries", "isolation_pass", "fixture_tokens_present"]}
                            for artifact in artifacts], dependency_audit=lock_audit), ensure_ascii=False))

