with zipfile.ZipFile(r/a['path']) as z:
 print('test_expected_sha256',a['sha256'],'expected_bytes',a['bytes'])
 print('test_current_sha256',hashlib.sha256((r/a['path']).read_bytes()).hexdigest(),'bytes',(r/a['path']).stat().st_size)
 print('archive_entries_equal',z.namelist()==a['archive_entries'])
 for abc in a['abc_files']:
  print('abc',abc['entry'],'expected',abc['sha256'],'actual',hashlib.sha256(z.read(abc['entry'])).hexdigest())
 for path,value in a['modules'].items():
  print('metadata_equal',path,json.loads(z.read(path))==value)
 for path,value in a['profiles'].items():
  print('profile_equal',path,json.loads(z.read(path))==value)
print('parent test immutable record candidates')
for p in sorted((r/'workflow/verification').glob('*v3*')):
 if p.is_file() and p.suffix=='.json':
  print(p.as_posix())
